INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(17801, 'Isaiah 65:17', 'Isaiah', 65, 17, '&nbsp;”ګورئ، زۀ نوى آسمانونه او نوې زمکه جوړوم. د تېرې زمانې څيزونه به نۀ شى يادولے، او نۀ به په خيال خاطر کښې راځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17802, 'Isaiah 65:18', 'Isaiah', 65, 18, '&nbsp;خوشحاله شئ. او زۀ چې څۀ پېدا کوم نو په هغې همېشه خوشحالى کوئ. ګورئ، زۀ به يروشلم د خوشحالۍ ځائ جوړ کړم، او د هغې خلق به د خوشحالۍ سبب وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17803, 'Isaiah 65:19', 'Isaiah', 65, 19, '&nbsp;زۀ پخپله به په يروشلم خوشحالى کوم، او د هغې په خلقو به خوشحاله يم. په هغې کښې به نور د ژړا شور او د پرېشانۍ چغې نۀ شى اورېدے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17804, 'Isaiah 65:20', 'Isaiah', 65, 20, '&nbsp;واړۀ ماشومان به نور په کم عُمر کښې نۀ مرى او ټول خلق به اوږدۀ عُمرونه تېروى. د چا عُمر چې صرف سل کاله وى نو هغه به هم ځوان ګڼلے شى. او څوک چې د سلو کالو نه مخکښې مړ شى نو هغه به لعنتى ګڼلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17805, 'Isaiah 65:21', 'Isaiah', 65, 21, '&nbsp;خلق به کورونه جوړوى او په خپله به په کښې اوسيږى، د انګورو باغونه به کَرى او په خپله به يې خورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17806, 'Isaiah 65:22', 'Isaiah', 65, 22, '&nbsp;بيا به داسې نۀ وى چې د کور جوړولو نه پس به بل څوک پکښې اوسيږى، او د باغ لګولو نه پس به بل څوک د دې مېوه خورى. زما د خلقو عُمرونه به د ونو په شان اوږدۀ وى. او زما غوره کړے شوى به د خپل محنت څيزونو نه ښۀ خوند اخلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17807, 'Isaiah 65:23', 'Isaiah', 65, 23, '&nbsp;د هغوئ خوارى به بې‌ځايه نۀ وى او د هغوئ بچى به د افت سره نۀ مخ کيږى. ځکه چې هغوئ به د مالِک خُدائ بختور خلق وى، هغوئ او د هغوئ اولاد به برکتناک وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17808, 'Isaiah 65:24', 'Isaiah', 65, 24, '&nbsp;د دې نه مخکښې چې هغوئ ما له آواز راکړى زۀ به جواب ورکړم. هغوئ به لا د خپلو حاجتونو په حقله خبرې کوى چې ما به د هغوئ دُعاګانې قبولې کړې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17809, 'Isaiah 65:25', 'Isaiah', 65, 25, '&nbsp;شرمخان او ګډې به يو ځائ خوراک کوى، زمريان به د څاروو په شان بوس خورى او ماران به خاورې خورى. زما په مقدس غر، صيون باندې به نۀ څۀ غلط کار کيږى او نۀ به چا ته څۀ نقصان رسى. ما، مالِک خُدائ دا فرمائيلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17810, 'Isaiah 66:1', 'Isaiah', 66, 1, '&nbsp;مالِک خُدائ فرمائى، ”آسمان زما تخت دے او زمکه زما د پښو چوکۍ ده. نو بيا هغه کور چرته دے چې تاسو يې زما دپاره جوړَوئ؟ هغه ځائ کوم دے چرته به چې زۀ آرام کوم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17811, 'Isaiah 66:2', 'Isaiah', 66, 2, '&nbsp;مالِک خُدائ فرمائى، ”ما په خپل لاس دا هر څۀ جوړ کړل، نو بيا دا په وجود کښې راغلل. زۀ د هغه خلقو خيال ساتم څوک چې عاجزان او توبه کوونکى دى، او زما د کلام په وړاندې د يرې نه ريږدى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17812, 'Isaiah 66:3', 'Isaiah', 66, 3, '&nbsp;خو څوک چې غوَيے حلال کړى هغه داسې دے لکه چې انسان حلال کړى، څوک چې يو ګډُورے حلال کړى هغه داسې دے لکه چې د يو سپى څټ مات کړى، څوک چې د غلې نذرانه پېش کړى هغه داسې دے لکه چې د خنزير وينه پېش کړى، څوک چې خوشبوئى پېش کړى هغه داسې دے لکه چې بُت پرستى وکړى. دې خلقو خپلې غلطې لارې خوښې کړې دى، او د دوئ ځان په خپلو حرامو څيزونو خوشحاليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17813, 'Isaiah 66:4', 'Isaiah', 66, 4, '&nbsp;زۀ به په هغوئ باندې لوئ مصيبت راولم، هغه ټول څيزونه چې دوئ ترې نه يرېدل. ځکه چې کله ما آواز ورکړو، نو هغوئ جواب رانۀ کړو، او چې کله مې ورسره کلام کولو، نو هغوئ اورېدو نه. او زما د سترګو په وړاندې هغوئ قصداً ګناه کوله او هغه څۀ به يې کول د څۀ چې هغوئ ته پته ده چې زۀ ترې نفرت کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17814, 'Isaiah 66:5', 'Isaiah', 66, 5, '&nbsp;اے تاسو ټول څوک چې د مالِک خُدائ د کلام په وړاندې ريږدئ، د هغۀ کلام واورئ، ”ستاسو خپل خلق ستاسو نه نفرت کوى او زما د نوم له وجې تاسو د خپلوالۍ نه وباسى. هغوئ په تاسو پورې خندا کوى او وائى، مالِک خُدائ دې خپله لوئى ښکاره کړى چې مونږ ستاسو خوشحالى ووينو. خو هغوئ به په خپله د شرم سره مخ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17815, 'Isaiah 66:6', 'Isaiah', 66, 6, '&nbsp;واورئ. په ښار کښې شور او غوغا، د خُدائ پاک په کور کښې آواز ته غوږ ونيسئ، دا د مالِک خُدائ آواز دے، خپلو دشمنانو له سزا ورکوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17816, 'Isaiah 66:7', 'Isaiah', 66, 7, '&nbsp;د ماشوم د پېدا کېدو درد نه مخکښې د يروشلم ماشوم وشو، د پېدايښت درد نه مخکښې د هغۀ زوئ پېدا شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17817, 'Isaiah 66:8', 'Isaiah', 66, 8, '&nbsp;چا داسې خبره اورېدلې ده؟ يا يې داسې څيز ليدلے دے؟ يو مُلک په يوه ورځ کښې پېدا کېدے شى؟ يا يو قوم په يوه لحظه کښې پېدا کېدے شى څۀ؟ خو صيون سره هم داسې شوى دى. د ماشوم د پېدا کېدو درد نه مخکښې د هغۀ ماشومان پېدا شول.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17818, 'Isaiah 66:9', 'Isaiah', 66, 9, '&nbsp;مالِک خُدائ فرمائى، ”ولې زۀ به دا قوم د پېدا کېدو حد ته راولم او بيا به يې پېدا کېدو ته نۀ پرېږدم؟ نه، هيڅکله نه.“ ستاسو خُدائ پاک فرمائى، ”زۀ به دا قوم هيڅکله د پېدا کېدو نه نۀ پاتې کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17819, 'Isaiah 66:10', 'Isaiah', 66, 10, '&nbsp;اے هغه ټولو خلقو چې څوک د دې ښار سره مينه کوئ، د يروشلم سره خندا او خوشحالى وکړئ. اے هغه ټولو خلقو چې په دې باندې غمژن وئ، نو اوس ورسره خوشحالۍ وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17820, 'Isaiah 66:11', 'Isaiah', 66, 11, '&nbsp;اوس به تاسو د هغې تسلۍ ورکولو والا سينې نه ښۀ په مړه ګېډه پئ وڅښئ، تاسو به د هغې ښائسته ډېرو پيو نه ښۀ خوند واخلئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17821, 'Isaiah 66:12', 'Isaiah', 66, 12, '&nbsp;مالِک خُدائ فرمائى، ”ګورئ، زۀ به د درياب په شان د يروشلم سلامتى زياته کړم، او د قومونو دولت به پرې لکه د سېلاب په شان راروان وى. بيا به تاسو د هغې سينه روئ، او هغه به تاسو په ډوډى ګرځوى، او په خپل غېږ کښې به مو ځنګوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17822, 'Isaiah 66:13', 'Isaiah', 66, 13, '&nbsp;لکه چې يوه مور خپل بچى له تسلى ورکوى، نو زۀ به په يروشلم کښې تاسو له داسې آرام درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17823, 'Isaiah 66:14', 'Isaiah', 66, 14, '&nbsp;کله چې تاسو دا څيزونه وګورئ نو ستاسو زړونه به خوشحاله شى، او د تازه شينکى په شان به زور کښې شئ. او هر څوک به ووينى چې د مالِک خُدائ لاس د هغۀ د خادِمانو سره دے، او د هغۀ غصه د هغۀ د دشمنانو خلاف ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17824, 'Isaiah 66:15', 'Isaiah', 66, 15, '&nbsp;ګورئ، مالِک خُدائ د اور په صورت کښې راروان دے، او د هغۀ جنګى ګاډۍ لکه د طوفان په شان غړمبيږى. هغه به سخت قهر سره او د اور د شغلو په شان سخت رټلو سره سزا ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17825, 'Isaiah 66:16', 'Isaiah', 66, 16, '&nbsp;مالِک خُدائ به اور او خپلې تُورې سره د دُنيا عدالت وکړى، او ډېر خلق به د هغۀ د لاسه ووژلے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17826, 'Isaiah 66:17', 'Isaiah', 66, 17, '&nbsp;مالِک خُدائ فرمائى، ”د هغه خلقو ختمېدل رانزدې دى څوک چې خپل ځانونه مقدس کوى او صفا کوى چې مقدسو باغونو ته لاړ شى او د هغې په مينځ کښې د بُتانو پيروى وکړى، د خنزير غوښه، ناولى څيزونه او منږکان وخورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17827, 'Isaiah 66:18', 'Isaiah', 66, 18, '&nbsp;ما ته د هغوئ د خيالونو او عملونو پته ده. زۀ ټول قومونه او جدا جدا ژبو وئيلو والا راغونډوم. هغوئ به راشى او زما جلال به ووينى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17828, 'Isaiah 66:19', 'Isaiah', 66, 19, '&nbsp;زۀ به د هغوئ په مينځ کښې يوه نښه قائمه کړم. او په هغوئ کښې چې کوم ژوندى پاتې وى نو څۀ به ترې نورو قومونو ته ولېږم. هغوئ به ترسيس، ليبيا او لِديه چې په غشو او ليندو استعمالولو کښې تکړه دى، او توبل او يونان ته ولېږم. او هغه لرې مُلکونو ته به يې ولېږم چې هغوئ زما د شُهرت نه نۀ دى خبر او چې زما جلال يې هم نۀ دے ليدلے. هغوئ به دغه قومونو ته زما د لويئ اعلان وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17829, 'Isaiah 66:20', 'Isaiah', 66, 20, '&nbsp;هغوئ به ستاسو باقى پاتې خلق د هر يو قوم نه واپس راولى. هغوئ به يې په يروشلم کښې زما مقدس غر ته مالِک خُدائ ته د نذرانې په توګه راولى. مالِک خُدائ فرمائى، هغوئ به يې په آسونو، قچرو، اوښانو، جنګى ګاډو، نورو ګاډو داسې راولى لکه څنګه چې بنى اِسرائيليان په پاکو لوښو کښې زما کور ته د غلې نذرانې راوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17830, 'Isaiah 66:21', 'Isaiah', 66, 21, '&nbsp;زۀ به د هغوئ نه څۀ کسان اِمامان او ليويان جوړ کړم. دا د مالِک خُدائ وينا ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17831, 'Isaiah 66:22', 'Isaiah', 66, 22, '&nbsp;مالِک خُدائ فرمائى، ”لکه څنګه به چې زما نوى آسمانونه او نوې زمکه زما په وړاندې قائمه وى، نو هم داسې به ستاسو اولاد او ستاسو نوم تر همېشه پورې قائم وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17832, 'Isaiah 66:23', 'Isaiah', 66, 23, '&nbsp;مالِک خُدائ فرمائى، ”د هرې نوې مياشتې په راختو او د هر سبت په ورځ به ټول خلق ما له راځى او زما عبادت به کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17833, 'Isaiah 66:24', 'Isaiah', 66, 24, '&nbsp;کله چې هغوئ د ښار نه بهر ځى نو هغوئ به د هغه خلقو لاشونه ووينى چا چې زما خِلاف سرکشى کړې وه. کوم چينجى چې دغه لاشونه خورى نو هغه به هيڅکله نۀ مرى او کوم اور چې هغوئ سوزوى نو هغه به نۀ مړ کيږى. د هغوئ دا منظر به د ټولو انسانانو دپاره يروونکے وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17834, 'Jeremiah 1:1', 'Jeremiah', 1, 1, '&nbsp;په دې کِتاب کښې د خِلقياه د زوئ يرمياه پېغامونه دى ‎څوک چې د بنيامين په علاقه کښې د عنتوت په ښار کښې د اِمامانو نه يو اِمام وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17835, 'Jeremiah 1:2', 'Jeremiah', 1, 2, '&nbsp;د مالِک خُدائ کلام په اول ځل په يرمياه د امون په زوئ يوسياه د يهوداه د بادشاهت په ديارلسم کال نازل شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17836, 'Jeremiah 1:3', 'Jeremiah', 1, 3, '&nbsp;او يرمياه ته دا پېغامونه تر دې چې د يهويقيم د يوسياه د زوئ د يهوداه بادشاه په ټول حکومت کښې او د يهوداه بادشاه د يوسياه د زوئ د صدقياه د حکومت د يوولسم کال تر پينځمې مياشتې پورې مِلاوېدل کله چې د يروشلم خلق جلاوطن کړے شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17837, 'Jeremiah 1:4', 'Jeremiah', 1, 4, '&nbsp;د مالِک خُدائ کلام په ما نازل شو او ما ته يې وفرمائيل،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17838, 'Jeremiah 1:5', 'Jeremiah', 1, 5, '&nbsp;”ما تۀ د هغه وخت نه پېژندلې چې لا د مور په خېټه شوے نۀ وې، ستا د پېدا کېدو نه وړاندې مې تۀ غوره کړې او د قومونو دپاره مې نبى مقرر کړې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17839, 'Jeremiah 1:6', 'Jeremiah', 1, 6, '&nbsp;خو ما ورته ووئيل چې، ”اے قادر مطلق خُدايه، ما ته خو د صحيح خبرو کولو طريقه هم نۀ راځى ځکه چې زۀ خو لا هلک يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17840, 'Jeremiah 1:7', 'Jeremiah', 1, 7, '&nbsp;خو مالِک خُدائ ما ته وفرمائيل چې، ”داسې مۀ وايه چې زۀ لا هلک يم ځکه زۀ چې هر چا ته تا ورلېږم نو تۀ به ورځې او هر څۀ چې درته وايم هغه به ورته وائې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17841, 'Jeremiah 1:8', 'Jeremiah', 1, 8, '&nbsp;د خلقو نه مۀ يرېږه، ځکه چې زۀ مالِک خُدائ دا وايم چې زۀ ستا مل يم، او زۀ به تا بچ ساتم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17842, 'Jeremiah 1:9', 'Jeremiah', 1, 9, '&nbsp;نو بيا مالِک خُدائ خپل لاس راوږد کړو، او زما خولې له يې راوړو او راته يې وفرمائيل، ”ګوره، ما خپل کلام ستا په خولۀ کښې واچولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17843, 'Jeremiah 1:10', 'Jeremiah', 1, 10, '&nbsp;نن ما تۀ په قومونو او بادشاهتونو باندې مقرر کړې، او تا ته مې په هغوئ د بېخ نه د راويستلو، او د هغوئ د رانسکورولو، بربادولو او د اخوا غورزولو، او په هغې د نورو د قائمولو او د کَرلو اختيار درکړو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17844, 'Jeremiah 1:11', 'Jeremiah', 1, 11, '&nbsp;نو بيا د مالِک خُدائ کلام په ما نازل شو او وې فرمائيل، ”يرمياه، تا ته څۀ ښکارى؟“ ما ورته ووئيل، ”ما ته د بادام د ونې يوه څانګه ښکارى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17845, 'Jeremiah 1:12', 'Jeremiah', 1, 12, '&nbsp;مالِک خُدائ راته وفرمائيل، ”تا ته ټيک ښکارى، د دې دا مطلب دے چې ‎‎‎‎‎‎زۀ د خپل کلام ساتونکے يم، زۀ چې څۀ وايم چې هغه پوره شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17846, 'Jeremiah 1:13', 'Jeremiah', 1, 13, '&nbsp;د مالِک خُدائ کلام دوباره په ما نازل شو او وې فرمائيل، ”نور څۀ وينې؟“ ما ورته ووئيل، ”زۀ د شمال طرف نه دېګ وينم چې څۀ په کښې يشيږى او د دېګ خولۀ زمونږ په طرف راټيټه ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17847, 'Jeremiah 1:14', 'Jeremiah', 1, 14, '&nbsp;نو مالِک خُدائ ما ته بيا وفرمائيل چې، ”دغه شان به په دې مُلک او څوک چې په کښې اوسيږى په هغوئ به د شمال نه د جنوب طرف ته افت راښکته شى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17848, 'Jeremiah 1:15', 'Jeremiah', 1, 15, '&nbsp;نو وګورئ، زۀ قومونه د شمال د بادشاهتونو نه راغونډوم. د دُنيا بادشاهان به يروشلم او د يهوداه په ټولو ښارونو حمله وکړى او هغوئ به خپل تختونه د يروشلم د ښار په دروازه کښې قائم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17849, 'Jeremiah 1:16', 'Jeremiah', 1, 16, '&nbsp;نو زۀ به خپله سزا په خپل غوره شوى قوم نازله کړم او د هغوئ د شرارت په وجه به هغوئ ته سزا ورکړم ځکه چې دوئ زۀ رد کړم او غېرو خُدايانو ته يې خوشبويانې وسوزولې او د خپلو لاسونو جوړو شوو بُتانو ته يې عبادت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17850, 'Jeremiah 1:17', 'Jeremiah', 1, 17, '&nbsp;نو تۀ يرمياه اوس ځان تيار کړه، او راپاڅه او هر هغه څۀ چې زۀ درته وايم دا هغوئ ته ووايه. د هغوئ نه مۀ يرېږه، ګنې زۀ به تا د هغوئ په وړاندې سخت ويروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17851, 'Jeremiah 1:18', 'Jeremiah', 1, 18, '&nbsp;ګوره، ما نن تۀ لکه د يو قلعه بند ښار په شان او د اوسپنې ستن، او د پيتلو د دېوال په شان مضبوط جوړ کړې چې تۀ د ټول مُلک سره مقابله وکړې، کۀ هغه د يهوداه بادشاهان، آفسران، اِمامان او يا د هغې ټول عوام وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17852, 'Jeremiah 1:19', 'Jeremiah', 1, 19, '&nbsp;هغوئ به ستا خلاف وجنګيږى خو کامياب به نۀ شى، ځکه چې زۀ ستا مل يم او زۀ به تا بچ کړم،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17853, 'Jeremiah 2:1', 'Jeremiah', 2, 1, '&nbsp;د مالِک خُدائ کلام په ما نازل شو او راته يې وفرمائيل چې،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17854, 'Jeremiah 2:2', 'Jeremiah', 2, 2, '&nbsp;”لاړ شه او د يروشلم خلقو ته دا پېغام ورسوه. ما ته ستاسو د ځوانۍ وفادارى ښۀ ياده ده، چې تاسو به څنګه لکه د ناوې په شان ما سره مينه کوله او تر دې چې په صحرا کښې چې په کښې کله هم څۀ نۀ کېدل بيا هم تاسو ما پسې راروان وئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17855, 'Jeremiah 2:3', 'Jeremiah', 2, 3, '&nbsp;په هغه ورځو کښې بنى اِسرائيل مالِک خُدائ ته مقدس خلق وُو او د هغۀ د فصل وړومبۍ مېوه وه. او چا به چې هغوئ ته نقصان رسولو نو هغوئ به ما مجرمان ګرځول او په هغوئ به مې مصيبتونه نازلول، ما مالِک خُدائ دا وفرمائيل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17856, 'Jeremiah 2:4', 'Jeremiah', 2, 4, '&nbsp;اے د يعقوب اولاده، اے د بنى اِسرائيلو ټولو قبيلو، د مالِک خُدائ کلام ته غوږ ونيسئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17857, 'Jeremiah 2:5', 'Jeremiah', 2, 5, '&nbsp;مالِک خُدائ فرمائى، ”ستاسو پلار نيکۀ په ما کښې څۀ غلطى ليدلې وه چې هغوئ زما نه دومره لرې شول؟ هغوئ د بې‌کاره بُتانو عبادت شروع کړو او په خپله هم بې‌کاره شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17858, 'Jeremiah 2:6', 'Jeremiah', 2, 6, '&nbsp;هغوئ دا تپوس قدرې هم ونۀ کړو چې، ”مالِک خُدائ چرته دے، چا چې مونږ د مِصر نه رابهر کړو، او په هغه صحرا کښې يې زمونږ لارښودنه وکړه چې د ميرو او کندو کپرو مُلک وو، هر طرف ته خُشکه او تيارۀ وه چې په کومه زمکه کښې نۀ چا سفر کولو او نۀ په کښې څوک اوسېدل؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17859, 'Jeremiah 2:7', 'Jeremiah', 2, 7, '&nbsp;ما تاسو د باغونو نه ډک او زرخيزه مُلک ته راوستلئ چې د دې د مېوو او د نورو ښو څيزونو نه خوند واخلئ. خو کله چې تاسو په هغه مُلک کښې ورداخل شوئ نو هغه تاسو په ګناه سره پليت کړو او په دې وجه مو زما ميراثى مُلک قابل نفرت وګرځولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17860, 'Jeremiah 2:8', 'Jeremiah', 2, 8, '&nbsp;اِمامانو هم دا تپوس ونۀ کړو چې، ”مالِک خُدائ چرته دے؟“ او تر دې چې د شريعت خادِمانو هم زۀ ونۀ پېژندم، د قوم مشرانو زما خلاف سرکشى وکړه، او د هغوئ نبيانو د بعل د بُت پېغام اورولو او د بې‌کاره بُتانو پيروى او عبادت يې کولو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17861, 'Jeremiah 2:9', 'Jeremiah', 2, 9, '&nbsp;مالِک خُدائ فرمائى چې، ”نو په دې وجه به زۀ د خپلو خلقو خلاف اِلزام ولګوم. او زۀ به ستاسو په اولاد هم نسل در نسل اِلزام ولګوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17862, 'Jeremiah 2:10', 'Jeremiah', 2, 10, '&nbsp;مغرب طرف ته د سمندر په بله خوا کښې د قبرص جزيرې ته لاړ شه او وګوره، او د مشرق طرف ته د قيدار مُلک ته څوک ولېږه چې په غور سره لټون وکړى چې آيا د دې نه وړاندې هم داسې کار شوے دے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17863, 'Jeremiah 2:11', 'Jeremiah', 2, 11, '&nbsp;تاسو چرې يو قوم داسې هم ليدلے دے چې د خپلو خُدايانو نه اوړېدلى وى کوم چې په حقيقت کښې خُدائ پاک هم نۀ دے؟ نه، بلکل نه. خو زما غوره شوے قوم زۀ خپل جلالى مالِک خُدائ پرېښودم او زما په ځائ يې د بې‌فائدې بُتانو عبادت وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17864, 'Jeremiah 2:12', 'Jeremiah', 2, 12, '&nbsp;اے آسمانونو تاسو خوف زده شئ او پرېشانه شئ،“ مالِک خُدائ فرمائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17865, 'Jeremiah 2:13', 'Jeremiah', 2, 13, '&nbsp;”ځکه چې زما خلقو دوه ګناهونه کړى دى، يو دا چې هغوئ زۀ چې د ژوندون د اوبو چينه يم پرېښودے يم، او بل دا چې د خپل ځان دپاره يې مات شوى تالابونه جوړ کړى دى په کوم کښې چې اوبۀ نۀ ايساريږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17866, 'Jeremiah 2:14', 'Jeremiah', 2, 14, '&nbsp;”ولې بنى اِسرائيليان غلامان دى څۀ؟ ولې هغوئ غلامان پېدا شوى دى څۀ؟ نو بيا ولې هغوئ اغوا کړے شول؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17867, 'Jeremiah 2:15', 'Jeremiah', 2, 15, '&nbsp;هغوئ د غړمبېدونکو زمرو په شان په دوئ باندې حمله وکړه، او د دوئ د زمکې نه يې صحرا جوړه کړه، او ښارونه يې ورته وسوزول او د اوسېدو نه يې وويستل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17868, 'Jeremiah 2:16', 'Jeremiah', 2, 16, '&nbsp;د دې نه علاوه، د ميمفِس او د تحفنحيس خلق راغلل او ستاسو سرونه يې وخرائېل او غلامان يې جوړ کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17869, 'Jeremiah 2:17', 'Jeremiah', 2, 17, '&nbsp;اے بنى اِسرائيلو، ولې دا تاسو په خپله په خپل ځان نۀ دى کړى څۀ؟ کله چې مالِک ستاسو خُدائ پاک ستاسو رهنمائى کوله نو بيا په هغه وخت کښې تاسو هغه پرېښودو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17870, 'Jeremiah 2:18', 'Jeremiah', 2, 18, '&nbsp;نو بيا مِصر ته د تلو او د دريائے نيل د اوبو څښلو څۀ فائده ده؟ او بيا اسور ته د تلو او د فرات د سيند د اوبو څښلو څۀ فائده ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17871, 'Jeremiah 2:19', 'Jeremiah', 2, 19, '&nbsp;ستاسو شرارت به تاسو له سزا درکړى، او زما نه ستاسو د اوړېدو په وجه به تاسو ورټلے شئ. نو بيا تاسو په دې غور وکړئ او ځان خبر کړئ چې دا به ستاسو دپاره څومره بده او ترخه وى کله چې تاسو مالِک خُدائ ستاسو خُدائ پاک پرېږدئ او تاسو د هغۀ نه، نۀ يرېږئ،“ مالِک خُدائ ربُ الافواج فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17872, 'Jeremiah 2:20', 'Jeremiah', 2, 20, '&nbsp;”اے بنى اِسرائيلو، تاسو د ډېر پخوا نه زما جغ د خپل څټ نه اخوا کړے دے او زما نه مو اِنکار کړے دے. تاسو ووئيل، ”زۀ به نور ستا بندګى نۀ کوم.“ په هره لوړه غونډۍ او د هرې شنې ونې لاندې څملاستئ او د کنجرو په شان مو زنا وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17873, 'Jeremiah 2:21', 'Jeremiah', 2, 21, '&nbsp;ما تاسو د نورو انګورو د ښو بوټو د مينځ نه غوره کړئ او په زمکه مې وکرلئ خو بيا تاسو ولې فاسد او په خراب او ځنګلى انګورو بوټى بدل شوئ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17874, 'Jeremiah 2:22', 'Jeremiah', 2, 22, '&nbsp;کۀ څۀ هم تاسو خپل ځان په سوډا او ډېر صابون باندې ووينځئ، خو بيا هم ستاسو د ګناه داغونه زما په وړاندې دى.“ دا د قادر مطلق خُدائ وينا ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17875, 'Jeremiah 2:23', 'Jeremiah', 2, 23, '&nbsp;”تۀ څنګه وائې چې ما خپل ځان نۀ دے ګنده کړے او د بعل د بُت پيروى مې نۀ ده کړى؟ ګوره تا په هغه دره کښې څنګه رفتار وکړو. لږ ځان سره سوچ وکړه چې تا هلته څۀ کړى دى. تۀ هغه اوښه يې چې وار يې راوړے وى او اخوا ديخوا منډې وهى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17876, 'Jeremiah 2:24', 'Jeremiah', 2, 24, '&nbsp;تۀ لکه د هغه ځنګلى خرې په شان يې چې په دشته کښې په مستۍ راغلې وى او آوازونه شروع کړى نو څوک د هغې شهوت قابو کولے شى؟ او هر يو صحرائى خر به بغېر د تکليف نه په هغې باندې سورېدے شى او هغه په خپله هغوئ ته نزدې ورځى ځکه چې هغه په مستۍ کښې راغلې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17877, 'Jeremiah 2:25', 'Jeremiah', 2, 25, '&nbsp;نو بيا دومره منډې مۀ وهه چې څپلۍ دې وشليږى او مرۍ دې اوچه شى. نو بيا تا ووئيل، چې نه، دا خبرې زما دپاره بې‌فائدې دى، زۀ د غېرو د بُتانو سره مينه کوم، او زۀ به د هغوئ پيروى کوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17878, 'Jeremiah 2:26', 'Jeremiah', 2, 26, '&nbsp;”اے بنى اِسرائيلو ستاسو ټول قوم او بادشاهان، مشران، اِمامان، او نبيان داسې شرمنده شئ لکه څنګه چې يو غل ونيولے شى او شرمنده وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17879, 'Jeremiah 2:27', 'Jeremiah', 2, 27, '&nbsp;دوئ د لرګى نه جوړ شوى بُت ته وائى چې تۀ زما پلار يې، او د کاڼى نه جوړ شوى بُت ته وائى چې تۀ زما مور يې. دوئ ټولو ما ته د مخ په ځائ شا کړې ده، خو چې کله هم څۀ تکليف ورباندې راشى نو بيا ما ته خواست کوى چې راشه او مونږ ته خلاصون راکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17880, 'Jeremiah 2:28', 'Jeremiah', 2, 28, '&nbsp;نو بيا هغه معبودان چرته دى کوم چې تاسو د خپل ځان دپاره جوړ کړى دى؟ نو بيا کۀ دوئ کولے شى نو را دې شى او د مصيبت په وخت کښې دې تاسو له خلاصون درکړى. ځکه چې اے يهوداه، ستاسو خو دومره ډېر معبودان دى لکه څومره چې ستا ښارونه دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17881, 'Jeremiah 2:29', 'Jeremiah', 2, 29, '&nbsp;مالِک خُدائ فرمائى چې، ”نو بيا تاسو ولې په ما اِلزام لګوئ؟ تاسو ټولو زما خلاف سرکشى کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17882, 'Jeremiah 2:30', 'Jeremiah', 2, 30, '&nbsp;ما ستاسو خلقو ته بې‌فائدې سزا ورکړه، ځکه چې هغوئ زما اصلاح ‎کول ونۀ منل. خو تاسو لکه د غړمبېدونکى زمرى په شان په خپلو نبيانو حمله وکړه او هغوئ مو قتل کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17883, 'Jeremiah 2:31', 'Jeremiah', 2, 31, '&nbsp;اے موجوده نسلونو، د مالِک خُدائ په کلام باندې غور او فکر وکړئ، ولې زۀ د بنى اِسرائيلو دپاره د صحرا او يا د تورې تيارې زمکې په شان وم څۀ؟ نو بيا ولې زما قوم داسې وائى چې اوس دوئ زما نه آزاد شُو، او بيا به هيڅکله ما ته واپس رانۀ شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17884, 'Jeremiah 2:32', 'Jeremiah', 2, 32, '&nbsp;ولې يوه پېغله خپل کالى هېروى، او يا يوه ناوې خپل د وادۀ سنګار او جامې هېروى څۀ؟ خو زما خلقو زۀ بې‌حده هېر کړے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17885, 'Jeremiah 2:33', 'Jeremiah', 2, 33, '&nbsp;د معشوقو په پېدا کولو کښې تاسو څومره ماهر يې. تر دې چې بدکاره ښځه به هم ستاسو نه چل زده کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17886, 'Jeremiah 2:34', 'Jeremiah', 2, 34, '&nbsp;ستاسو لمن د بې‌ګناه غريبانانو په وينو داغې شوې ده، سره د دې چې هغوئ تاسو په غلا کولو کښې نۀ دى نيولى. د دې هر څۀ باوجود', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17887, 'Jeremiah 2:35', 'Jeremiah', 2, 35, '&nbsp;بيا هم تۀ وائې چې، ”ما هيڅ نۀ دى کړى زۀ بې‌ګناه يم، مالِک خُدائ خو ما ته غصه نۀ دے.“ خو زۀ به تا له سخته سزا درکړم ځکه چې تۀ وائې چې، ”زۀ بې‌ګناه يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17888, 'Jeremiah 2:36', 'Jeremiah', 2, 36, '&nbsp;تۀ کله دلته او کله هلته ځې راځې نو بيا ولې دومره زر خپلې لارې بدلوې؟ تۀ به د مِصر نه داسې وشرمېږې لکه څنګه چې تۀ وړاندې د اسور نه شرمېدلے وې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17889, 'Jeremiah 2:37', 'Jeremiah', 2, 37, '&nbsp;تۀ به د هغه ځائ نه هم لاس په سر شرمنده وځې، ځکه چې په چا تا بهروسه کوله مالِک خُدائ هغوئ رد کړل نو تاسو به د هغوئ نه هيڅ امداد حاصل نۀ کړئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17890, 'Jeremiah 3:1', 'Jeremiah', 3, 1, '&nbsp;مالِک خُدائ فرمائى، ”کۀ يو سړے خپله ښځه طلاقه کړى او د هغۀ نه جدا شى او بيا هغه د بل چا سره وادۀ وکړى نو آيا بيا اول خاوند ته د دې سره د دوباره وادۀ کولو اجازت شته څۀ؟ بلکل نه، ولې چې په داسې کولو به ټوله زمکه پوره پليته نۀ شى څۀ؟ خو اے اِسرائيله لکه څنګه چې يوه زناکاره ښځه په ډېرو سړو پسې ګرځى دغه شان تاسو په ډېرو بُتانو پسې وګرځېدئ نو اوس تاسو غواړئ چې ما ته دوباره راشئ څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17891, 'Jeremiah 3:2', 'Jeremiah', 3, 2, '&nbsp;د اوچتو خُشکو غرونو طرف ته نظر وکړه او وګوره چې آيا هلته په هغې کښې داسې ځائ شته چې تۀ په کښې بې‌حرمته شوے نۀ يې؟ د لارې په خوا کښې تۀ د زنا دپاره يارانو ته داسې ولاړه وې، لکه چې يو کوچے په صحرا کښې په انتظار ناست وى. تا د زناکارۍ او شرارت په وجه ټوله زمکه پليته کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17892, 'Jeremiah 3:3', 'Jeremiah', 3, 3, '&nbsp;نو باران په دې وجه ايسار شوے وو او د سپرلى څاڅکى ونۀ ورېدل. نو دا چې تا د کنجرى شکل نيولے دے او تا له هيڅ شرم نۀ درځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17893, 'Jeremiah 3:4', 'Jeremiah', 3, 4, '&nbsp;تۀ د دومره بې‌شرمۍ باوجود بيا هم ما ته وائې چې، ”اے پلاره، کله چې زۀ وړه وم، تا ما سره مينه کوله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17894, 'Jeremiah 3:5', 'Jeremiah', 3, 5, '&nbsp;ولې تۀ به د تل دپاره ما ته په قهر يې څۀ؟ ولې ستا غضب به د تل دپاره په مونږ باندې وى څۀ؟“ تۀ خو داسې وائې مګر څومره بدعملى چې تا نه کېدے شى دومره کوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17895, 'Jeremiah 3:6', 'Jeremiah', 3, 6, '&nbsp;د يوسياه بادشاه د حکومت په دوران کښې مالِک خُدائ ما ته وفرمائيل، ”تا هغه څۀ وليدل کوم چې بې‌وفا اِسرائيل کړى دى؟ لکه د يوې بدکارې ښځې په شان هغې په هر يو اوچت غرۀ او د هرې شنې ونې د سورى لاندې زنا کړې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17896, 'Jeremiah 3:7', 'Jeremiah', 3, 7, '&nbsp;زما خيال دا وو چې د دې هر څۀ کولو نه وروستو به هغه ما ته واپس راوګرځى. خو دا راونۀ ګرځېده او د دې بې‌وفا خور يهوداه دا هر څۀ وليدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17897, 'Jeremiah 3:8', 'Jeremiah', 3, 8, '&nbsp;ما بې‌وفا اِسرائيل ته د هغې د زناکارۍ په وجه طلاق نامه ورکړه او ومې شړله نو بيا ما وليدل چې د هغې خور يهوداه نۀ يرېدله. هغه هم بهر ووتله او زناکارى يې شروع کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17898, 'Jeremiah 3:9', 'Jeremiah', 3, 9, '&nbsp;ځکه چې د اِسرائيل دغه بدکارى هغې ته ډېره بې‌اهميته ښکارېده نو هغې هغه زمکه پليته کړه چې د کاڼو او لرګو د بُتانو سره يې زنا شروع کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17899, 'Jeremiah 3:10', 'Jeremiah', 3, 10, '&nbsp;خو د دې هر څۀ باوجود، د هغې بې‌وفا خور يهوداه ما ته په پوره زړۀ سره راونۀ ګرځېدله، خو صرف په ظاهرى شکل سره زما طرف ته راواپس شوه. دا د مالِک خُدائ فرمان دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17900, 'Jeremiah 3:11', 'Jeremiah', 3, 11, '&nbsp;نو بيا مالِک خُدائ ما ته وفرمائيل چې، ”خو بيا دا چې بې‌ايمانه اِسرائيل د دوکه باز يهوداه نه صادق دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');